// LoadoutConfigReset restores LoadoutConfig's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func LoadoutConfigReset(value *LoadoutConfig) {
	value.Grade = GradeSilver
	clear(value.Grades[:])
	value.GradesCount = 0
	clear(value.Podium[:])
	value.Perks = 0
	WeaponConfigReset(&value.Primary)
	for i := range value.Backups {
		WeaponConfigReset(&value.Backups[i])
	}
	for i := range value.Attachments {
		AttachmentReset(&value.Attachments[i])
	}
	value.AttachmentsCount = 0
}

