// ProfileConfigReset restores ProfileConfig's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func ProfileConfigReset(value *ProfileConfig) {
	clear(value.Name[:])
	value.NameLength = 0
	clear(value.Icon[:])
	value.IconLength = 0
	value.Experience = 0
	value.Tilt = 0
	value.Heading = 0
	value.Timestamp = 0
	value.Badge = 0
	value.Port = 0
	value.Epoch = 0
	value.Precision = 0.0
	clear(value.Ratings[:])
	value.HasLoadout = false
	LoadoutConfigReset(&value.Loadout)
}

func ProfileConfigMeasureBody(value *ProfileConfig, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !ProfileConfigSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func ProfileConfigMeasure(value *ProfileConfig) int64 {
	var ids TableIds
	w := TableWriter{Measuring: true, Ids: &ids}
	w.Put8(1)
	if !ProfileConfigSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func ProfileConfigMeasureReason(value *ProfileConfig) (int64, error) {
	size := ProfileConfigMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
