// AttachmentReset restores Attachment's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func AttachmentReset(value *AttachmentRow) {
	value.Slot = 0
	value.Power = 1.0
}

func AttachmentMeasureBody(value *AttachmentRow, ids *TableIds) int64 {
	bytes := int64(1)
	if (value.Slot != 0) && (value.Slot < 0 || value.Slot > 7) {
		return -1
	}
	if value.Slot != 0 {
		bytes += tableLebBytes(ids.refAtHit(59, 0x6a771618f6fe31d1)) + 1 + 4
	} // slot
	if (math.Float32bits(value.Power) != math.Float32bits(1.0)) && (value.Power-value.Power != 0) {
		return -1
	}
	if math.Float32bits(value.Power) != math.Float32bits(1.0) {
		bytes += tableLebBytes(ids.refAtHit(140, 0xeef9d1358ae7b4e6)) + 1 + 4
	} // power
	if ids.Overflow {
		return -1
	}
	return bytes
}

func AttachmentMeasure(value *AttachmentRow) int64 {
	var ids TableIds
	body := AttachmentMeasureBody(value, &ids)
	if body < 0 || ids.Overflow {
		return -1
	}
	return 1 + body + int64(ids.Count)*8 + 8
}

func AttachmentMeasureReason(value *AttachmentRow) (int64, error) {
	size := AttachmentMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
func AttachmentSaveBody(w *TableWriter, value *AttachmentRow) bool {
	if !AttachmentSaveBodyFields(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
func AttachmentSaveBodyFields(w *TableWriter, value *AttachmentRow) bool {
	{
		if value.Slot != 0 {
			if ref := w.Ids.refAtHit(59, 0x6a771618f6fe31d1); !w.headerPair(ref, 4) {
				w.headerRest(ref, 4)
			}
			if value.Slot < 0 || value.Slot > 7 {
				return false
			}
			w.Put32(uint32(value.Slot))
		}
	}
	{
		if math.Float32bits(value.Power) != math.Float32bits(1.0) {
			if ref := w.Ids.refAtHit(140, 0xeef9d1358ae7b4e6); !w.headerPair(ref, 10) {
				w.headerRest(ref, 10)
			}
			if value.Power-value.Power != 0 {
				return false
			}
			w.Put32(math.Float32bits(value.Power))
		}
	}
	return !w.Overflow && !w.Ids.Overflow
}

func AttachmentSave(value *AttachmentRow, buffer []byte) int64 {
	var ids TableIds
	w := TableWriter{Buffer: buffer, Ids: &ids}
	w.Put8(1)
	if !AttachmentSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

